// Cloudflare Workers entry point. Wraps the OpenNext-generated worker so the
// per-request MongoDB client opened by lib/db.ts is closed once the response
// has been fully sent (see the Workers notes in lib/db.ts).
import { DurableObject } from "cloudflare:workers";
// @ts-ignore `.open-next/worker.js` is generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

const REQUEST_DBS = Symbol.for("valueplus.requestDbs");

function closeRequestDb(ctx: ExecutionContext) {
  const requestDbs: WeakMap<object, { client: { close(): Promise<void> } }> | undefined =
    (globalThis as any)[REQUEST_DBS];
  const entry = requestDbs?.get(ctx);
  if (!entry) return Promise.resolve();
  requestDbs!.delete(ctx);
  return entry.client.close().catch(() => {});
}

// Local-only maintenance/debug routes. None of them check who is calling
// (/api/seed wipes and re-seeds the whole database, import-stock deletes every
// item), several read files from the developer's disk, and the UI never calls
// them — so the public deployment does not serve them at all.
const BLOCKED_API_PREFIXES = [
  "/api/seed",
  // Resets the demo accounts (admin@valueplus.in …) to default passwords;
  // NextAuth's middleware skips /api/auth/*, so nothing else guards it.
  "/api/auth/seed",
  "/api/install-deps",
  "/api/test-login",
  "/api/fix-invoices",
  "/api/db-check",
  "/api/admin/import-stock",
  "/api/admin/import-stock4",
  "/api/admin/debug-stock",
];

function isBlocked(pathname: string) {
  const path = pathname.toLowerCase().replace(/\/+$/, "");
  return BLOCKED_API_PREFIXES.some((p) => path === p || path.startsWith(`${p}/`));
}

export default {
  async fetch(request: Request, env: unknown, ctx: ExecutionContext): Promise<Response> {
    if (isBlocked(new URL(request.url).pathname)) {
      return new Response("Not found", { status: 404 });
    }

    let response: Response;
    try {
      response = await handler.fetch(request, env, ctx);
    } catch (e) {
      ctx.waitUntil(closeRequestDb(ctx));
      throw e;
    }

    const requestDbs = (globalThis as any)[REQUEST_DBS] as WeakMap<object, unknown> | undefined;
    if (!requestDbs?.has(ctx)) {
      return response;
    }

    // A streamed body may still be reading from the database, so wait for it
    // to finish before closing the client.
    if (!response.body || (response as any).webSocket) {
      ctx.waitUntil(closeRequestDb(ctx));
      return response;
    }
    const { readable, writable } = new TransformStream();
    ctx.waitUntil(
      response.body
        .pipeTo(writable)
        .catch(() => {})
        .finally(() => closeRequestDb(ctx))
    );
    return new Response(readable, response);
  },
};

// @ts-ignore
export * from "./.open-next/worker.js";

// An earlier deployment of the production Worker ran the app inside this
// Durable Object, and Cloudflare refuses a new version that drops a class an
// existing namespace depends on. It is no longer used for any request; it is
// kept (instead of a delete-class migration) so a rollback to that older
// version stays possible.
export class AppServer extends DurableObject {
  async fetch(): Promise<Response> {
    return new Response("Not found", { status: 404 });
  }
}
